import hashlib
import json
import os
from collections.abc import Sequence
from pathlib import Path
from typing import Literal, Protocol

import yaml
from openai import OpenAI
from pydantic import BaseModel, create_model

from meal_planner.recipes import Recipe

# Bump to re-judge every recipe after changing how similarity is judged.
JUDGEMENT_VERSION = 1
DEFAULT_OPENAI_MODEL = "gpt-5-mini"
MAX_INSTRUCTION_CHARS = 2000

_CACHE_HEADER = """\
# Which nursery lunch dishes each dinner recipe is the same as, or very similar to.
# Generated by automations/meal_planner and committed so each recipe is only judged once.
# You can hand-edit `similar_lunch_dishes`; an entry is re-judged (overwriting any edits)
# when its recipe or the nursery menu changes, as that changes its `fingerprint`.
"""

_SYSTEM_PROMPT = """\
You help plan a toddler's dinners in Spain. At lunchtime he eats at nursery, and his dinner \
must not repeat what he had for lunch that day.

You are given one dinner recipe and the list of every dish on the nursery's lunch menu. \
Return the lunch dishes that are the same meal as the dinner, or so similar that eating both \
on the same day would feel like having the same meal twice. For example: the same dish under \
another name or in another language, the same main ingredient cooked in the same style (two \
chicken stews, two potato omelettes, two lentil dishes, pasta with a meat and tomato sauce \
versus pasta boloñesa), or two blended vegetable soups.

Don't count dishes as similar just because they share a minor ingredient, a side salad or a \
cooking method while the main ingredients differ. Most recipes are similar to none or only a \
few of the dishes. Lunch dish names are in Spanish; recipes may be in English or Spanish."""


class SimilarityJudge(Protocol):
    """Something that can decide which lunch dishes a recipe is too similar to."""

    def similar_dishes(self, recipe: Recipe, dishes: Sequence[str]) -> list[str]:
        """Return the subset of `dishes` that `recipe` is the same as or very similar to."""
        ...


class OpenAISimilarityJudge:
    """Judges recipe to lunch dish similarity with an OpenAI model."""

    def __init__(self, client: OpenAI, model: str = DEFAULT_OPENAI_MODEL) -> None:
        """Create a judge.

        Args:
            client: OpenAI API client.
            model: Name of the OpenAI model to use.
        """
        self._client = client
        self._model = model

    @classmethod
    def from_env(cls) -> "OpenAISimilarityJudge | None":
        """Create a judge from the `OAI_KEY` (and optional `OPENAI_MODEL`) env vars.

        Returns:
            The judge, or None if `OAI_KEY` is not set.
        """
        api_key = os.environ.get("OAI_KEY")
        if not api_key:
            return None
        return cls(
            OpenAI(api_key=api_key),
            model=os.environ.get("OPENAI_MODEL") or DEFAULT_OPENAI_MODEL,
        )

    def similar_dishes(self, recipe: Recipe, dishes: Sequence[str]) -> list[str]:
        """Return the subset of `dishes` that `recipe` is the same as or very similar to.

        Args:
            recipe: The dinner recipe.
            dishes: Every dish on the nursery lunch menu.

        Returns:
            The similar dishes, sorted.

        Raises:
            RuntimeError: If the model refuses or doesn't return a parseable answer.
        """
        judgement_model = create_model(
            "SimilarDishes",
            similar_dishes=(list[Literal[tuple(dishes)]], ...),  # type: ignore[valid-type]
        )
        recipe_description = {
            "title": recipe.title,
            "ingredients": list(recipe.ingredients),
            "method": recipe.instructions[:MAX_INSTRUCTION_CHARS],
        }
        completion = self._client.chat.completions.parse(
            model=self._model,
            messages=[
                {"role": "system", "content": _SYSTEM_PROMPT},
                {
                    "role": "user",
                    "content": (
                        f"Dinner recipe:\n{json.dumps(recipe_description, ensure_ascii=False, indent=2)}"
                        f"\n\nNursery lunch dishes:\n{json.dumps(list(dishes), ensure_ascii=False)}"
                    ),
                },
            ],
            response_format=judgement_model,
        )
        message = completion.choices[0].message
        parsed: BaseModel | None = message.parsed
        if parsed is None:
            raise RuntimeError(
                f"OpenAI gave no similarity judgement for recipe '{recipe.slug}': "
                f"{message.refusal or message.content!r}"
            )
        return sorted(set(parsed.similar_dishes))  # type: ignore[attr-defined]


def fingerprint(recipe: Recipe, dishes: Sequence[str]) -> str:
    """Return a short hash of everything a similarity judgement for `recipe` depends on."""
    payload = json.dumps(
        {
            "version": JUDGEMENT_VERSION,
            "title": recipe.title,
            "ingredients": list(recipe.ingredients),
            "instructions": recipe.instructions,
            "dishes": sorted(dishes),
        },
        ensure_ascii=False,
        sort_keys=True,
    )
    return hashlib.sha256(payload.encode()).hexdigest()[:16]


class LunchSimilarity:
    """Similarity judgements between dinner recipes and nursery lunch dishes, cached in a file."""

    def __init__(self, cache_path: Path, judge: SimilarityJudge | None) -> None:
        """Create the store.

        Args:
            cache_path: YAML file the judgements are cached in; created if it doesn't exist.
            judge: Used to judge recipes that aren't cached yet. If None, every recipe must
                already be cached.
        """
        self._cache_path = cache_path
        self._judge = judge

    def resolve(
        self, recipes: Sequence[Recipe], dishes: Sequence[str]
    ) -> dict[str, frozenset[str]]:
        """Return the lunch dishes each recipe is too similar to, judging any not yet cached.

        The cache is rewritten to hold exactly the given recipes.

        Args:
            recipes: The candidate dinner recipes.
            dishes: Every dish on the nursery lunch menu.

        Returns:
            Mapping of recipe slug to the set of lunch dishes it is the same as or very similar to.

        Raises:
            RuntimeError: If some recipes need judging but no judge was provided.
            ValueError: If the cache names a dish that isn't on the menu.
        """
        cache = self._load()
        known_dishes = set(dishes)
        stale = [
            recipe
            for recipe in recipes
            if cache.get(recipe.slug, {}).get("fingerprint")
            != fingerprint(recipe, dishes)
        ]
        if stale and self._judge is None:
            raise RuntimeError(
                "These dinner recipes are new or have changed, and need their similarity to the "
                f"nursery lunch menu judging: {', '.join(r.slug for r in stale)}. Set the OAI_KEY "
                "environment variable to an OpenAI API key so they can be judged."
            )

        for recipe in stale:
            assert self._judge is not None
            cache[recipe.slug] = {
                "fingerprint": fingerprint(recipe, dishes),
                "similar_lunch_dishes": self._judge.similar_dishes(recipe, dishes),
            }

        result = {}
        for recipe in recipes:
            similar = cache[recipe.slug].get("similar_lunch_dishes") or []
            unknown = set(similar) - known_dishes
            if unknown:
                raise ValueError(
                    f"{self._cache_path} lists dishes for '{recipe.slug}' that aren't on the nursery "
                    f"menu: {', '.join(sorted(unknown))}"
                )
            result[recipe.slug] = frozenset(similar)

        wanted = {recipe.slug: cache[recipe.slug] for recipe in recipes}
        if wanted != cache or stale:
            self._save(wanted)
        return result

    def _load(self) -> dict[str, dict]:
        if not self._cache_path.exists():
            return {}
        with open(self._cache_path) as fp:
            cache = yaml.safe_load(fp) or {}
        if not isinstance(cache, dict):
            raise ValueError(
                f"{self._cache_path} should contain a mapping of recipe slug to judgement"
            )
        return cache

    def _save(self, cache: dict[str, dict]) -> None:
        with open(self._cache_path, "w") as fp:
            fp.write(_CACHE_HEADER)
            yaml.safe_dump(cache, fp, allow_unicode=True, sort_keys=True)
